struct Rectangle {
    width: u32,
    height: u32,
}

impl Rectangle {
    fn new(width: u32, height: u32) -> Self {
        Rectangle { width, height }
    }
    fn area(&self) -> u32 {
        self.width * self.height
    }
}

questions.question:
关于所有权转移（Move），以下代码片段的运行结果是什么？
let s1 = String::from("hello");
let s2 = s1;
println!("{}", s1);

分析以下代码，哪一行会导致编译失败？
fn main() {
    let mut s = String::from("hello");
    let r1 = &s;      // Line A
    let r2 = &mut s;  // Line B
    println!("{}", r1);
}

